16	pub(crate) use lexical::is_identifier_continue;
17	use lexical::{previous_significant_byte, unsupported_at_construct};
18	use stack::TinyStack;
19	
20	pub(crate) struct Scanner<'a> {
21	    bytes: &'a [u8],
22	    tokens: Vec<StructuralToken>,
23	    nodes: Vec<SyntaxNode>,
24	    clauses: Vec<Clause>,
25	    embedded_tokens: Vec<EmbeddedToken>,
26	    dynamic_tags: Vec<DynamicTag>,
27	    dynamic_comments: Vec<ByteSpan>,
28	    style_blocks: Vec<StyleBlock>,
29	    first_root: u32,
30	    last_root: u32,
31	    parents: Vec<u32>,
32	}
