34	pub(crate) fn source_fingerprint(bytes: &[u8]) -> u128 {
35	    let mut first = 0x9e37_79b1_85eb_ca87_u64 ^ bytes.len() as u64;
36	    let mut second = 0xc2b2_ae3d_27d4_eb4f_u64 ^ (bytes.len() as u64).rotate_left(17);
37	    for chunk in bytes.chunks(8) {
38	        let mut word = [0_u8; 8];
39	        word[..chunk.len()].copy_from_slice(chunk);
40	        let value = u64::from_le_bytes(word);
41	        first = (first ^ value).wrapping_mul(0x9e37_79b1_85eb_ca87).rotate_left(27);
42	        second =
43	            (second ^ value.rotate_left(31)).wrapping_mul(0xc2b2_ae3d_27d4_eb4f).rotate_left(33);
44	    }
45	    (u128::from(first) << 64) | u128::from(second)
46	}
47	
48	impl<'a> Scanner<'a> {
49	    pub(crate) fn new(source: &'a str) -> Self {
50	        let bytes = source.as_bytes();
51	        Self {
52	            bytes,
53	            tokens: Vec::with_capacity(bytes.len().div_ceil(384)),
54	            nodes: Vec::with_capacity(bytes.len().div_ceil(1024)),
55	            clauses: Vec::with_capacity(bytes.len().div_ceil(512)),
56	            // Dynamic tags and raw styles are sparse. Keep the common zero-syntax path free of
57	            // avoidable heap allocations; the flat vectors grow after the first commit.
58	            embedded_tokens: Vec::new(),
59	            dynamic_tags: Vec::new(),
60	            dynamic_comments: Vec::new(),
61	            style_blocks: Vec::new(),
62	            first_root: NONE,
63	            last_root: NONE,
64	            parents: Vec::with_capacity(8),
65	        }
66	    }
67	
68	    pub(crate) fn finish(mut self) -> Result<Overlay, ProjectionError> {
69	        let source_len = to_u32(self.bytes.len())?;
70	        self.scan_region(0, None)?;
71	        Ok(Overlay {
72	            source_len,
73	            source_fingerprint: source_fingerprint(self.bytes),
74	            tokens: self.tokens,
75	            nodes: self.nodes,
76	            clauses: self.clauses,
77	            embedded_tokens: self.embedded_tokens,
78	            parser_dynamic_tokens: Vec::new(),
79	            parser_code_blocks: Vec::new(),
80	            parser_shorthand_attributes: Vec::new(),
81	            parser_lazy_patterns: Vec::new(),
82	            dynamic_tags: self.dynamic_tags,
83	            dynamic_comments: self.dynamic_comments,
84	            style_blocks: self.style_blocks,
85	            script_blocks: Vec::new(),
86	            first_root: self.first_root,
87	            last_root: self.last_root,
88	        })
89	    }
90	
91	    #[expect(
92	        clippy::too_many_lines,
93	        reason = "a byte-level scanner state machine whose arms only make sense read in source order"
94	    )]
95	    fn scan_region(
96	        &mut self,
97	        mut index: usize,
98	        closing: Option<u8>,
99	    ) -> Result<usize, ProjectionError> {
100	        let mut delimiters = TinyStack::<(u8, bool), 16>::new();
101	        if let Some(closing) = closing {
102	            delimiters.push((closing, closing == b'}'));
103	        }
104	        let mut can_start_expression = true;
105	        let mut can_start_jsx = true;
106	        let mut pending_control_paren = false;
107	        let mut closed_control_paren = false;
108	        let mut parens = TinyStack::<bool, 16>::new();
109	
110	        while index < self.bytes.len() {
111	            let byte = self.bytes[index];
112	            if byte.is_ascii_whitespace() {
113	                index += 1;
114	                continue;
115	            }
116	
117	            match byte {
118	                b'\'' | b'"' => {
119	                    index = self.skip_quote(index, byte)?;
120	                    can_start_expression = false;
121	                    can_start_jsx = false;
122	                    pending_control_paren = false;
123	                    closed_control_paren = false;
124	                }
125	                b'`' => {
126	                    index = self.scan_template(index)?;
127	                    can_start_expression = false;
128	                    can_start_jsx = false;
129	                    pending_control_paren = false;
130	                    closed_control_paren = false;
131	                }
132	                b'/' if self.bytes.get(index + 1) == Some(&b'/') => {
133	                    index = self.skip_line_comment(index + 2);
134	                }
135	                b'/' if self.bytes.get(index + 1) == Some(&b'*') => {
136	                    index = self.skip_block_comment(index)?;
137	                }
138	                b'/' if can_start_expression => {
139	                    index = self.skip_regex(index)?;
140	                    can_start_expression = false;
141	                    can_start_jsx = false;
142	                    pending_control_paren = false;
143	                    closed_control_paren = false;
144	                }
145	                b'/' => {
146	                    index += usize::from(self.bytes.get(index + 1) == Some(&b'=')) + 1;
147	                    can_start_expression = true;
148	                    can_start_jsx = true;
149	                    pending_control_paren = false;
150	                    closed_control_paren = false;
151	                }
152	                b'<' if can_start_jsx
153	                    && self.looks_like_jsx_start(index)
154	                    && !self.looks_like_typescript_type_parameters(index) =>
155	                {
156	                    let checkpoint = self.checkpoint();
157	                    let committed = self.committed_jsx_opening(index);
158	                    match self.scan_jsx_element(index) {
159	                        Ok(end) => {
160	                            index = end;
161	                            can_start_expression = false;
162	                            can_start_jsx = true;
163	                            pending_control_paren = false;
164	                            closed_control_paren = false;
165	                        }
166	                        Err(ProjectionError::UnsupportedSyntax { offset, construct }) => {
167	                            return Err(ProjectionError::UnsupportedSyntax { offset, construct });
168	                        }
169	                        Err(error) if committed => return Err(error),
170	                        Err(_) => {
171	                            self.rollback(checkpoint);
172	                            index += 1;
173	                            can_start_expression = true;
174	                            can_start_jsx = false;
175	                            pending_control_paren = false;
176	                            closed_control_paren = false;
177	                        }
178	                    }
179	                }
180	                b'@' if self.keyword_at(index, b"if") => {
181	                    index = self.parse_if(index, self.code_context(index))?;
182	                    can_start_expression = false;
183	                    can_start_jsx = true;
184	                    pending_control_paren = false;
185	                    closed_control_paren = false;
186	                }
187	                b'@' if self.keyword_at(index, b"for") => {
188	                    index = self.parse_for(index, self.code_context(index))?;
189	                    can_start_expression = false;
190	                    can_start_jsx = true;
191	                    pending_control_paren = false;
192	                    closed_control_paren = false;
193	                }
194	                b'@' if self.keyword_at(index, b"switch") => {
195	                    index = self.parse_switch(index, self.code_context(index))?;
196	                    can_start_expression = false;
197	                    can_start_jsx = true;
198	                    pending_control_paren = false;
199	                    closed_control_paren = false;
200	                }
201	                b'@' if self.keyword_at(index, b"try") => {
202	                    index = self.parse_try(index, self.code_context(index))?;
203	                    can_start_expression = false;
204	                    can_start_jsx = true;
205	                    pending_control_paren = false;
206	                    closed_control_paren = false;
207	                }
208	                b'@' if self.bytes.get(index + 1) == Some(&b'{') => {
209	                    self.push_token(StructuralKind::FunctionBody, index)?;
210	                    index += 1;
211	                    can_start_expression = true;
212	                    can_start_jsx = true;
213	                    pending_control_paren = false;
214	                    closed_control_paren = false;
215	                }
216	                b'@' => {
217	                    if self.keyword_at(index, b"else")
218	                        || self.keyword_at(index, b"empty")
219	                        || self.keyword_at(index, b"case")
220	                        || self.keyword_at(index, b"default")
221	                        || self.keyword_at(index, b"pending")
222	                        || self.keyword_at(index, b"catch")
223	                    {
224	                        return Err(ProjectionError::MalformedSyntax {
225	                            offset: to_u32(index)?,
226	                            expected: "an owning TSRX control",
227	                        });
228	                    }
229	                    if let Some(construct) = unsupported_at_construct(self.bytes, index) {
230	                        return Err(ProjectionError::UnsupportedSyntax {
231	                            offset: to_u32(index)?,
232	                            construct,
233	                        });
234	                    }
235	                    index += 1;
236	                    can_start_expression = true;
237	                    can_start_jsx = true;
238	                    pending_control_paren = false;
239	                    closed_control_paren = false;
240	                }
241	                b'(' | b'[' | b'{' => {
242	                    let close = match byte {
243	                        b'(' => b')',
244	                        b'[' => b']',
245	                        b'{' => b'}',
246	                        _ => unreachable!(),
247	                    };
248	                    let previous = previous_significant_byte(self.bytes, index);
249	                    let block = byte == b'{'
250	                        && (!can_start_expression
251	                            || closed_control_paren
252	                            || previous == Some(b'@')
253	                            || previous == Some(b';')
254	                            || previous == Some(b'}')
255	                            || previous == Some(b'>')
256	                                && previous_significant_byte(self.bytes, index.saturating_sub(1))
257	                                    == Some(b'='));
258	                    delimiters.push((close, block));
259	                    if byte == b'(' {
260	                        parens.push(pending_control_paren);
261	                    }
262	                    pending_control_paren = false;
263	                    closed_control_paren = false;
264	                    index += 1;
265	                    can_start_expression = true;
266	                    can_start_jsx = true;
267	                }
268	                b')' | b']' | b'}' => {
269	                    let mut closed_block = false;
270	                    if delimiters.last().is_some_and(|delimiter| delimiter.0 == byte) {
271	                        closed_block = delimiters.pop().is_some_and(|delimiter| delimiter.1);
272	                        index += 1;
273	                        if delimiters.is_empty() && closing.is_some() {
274	                            return Ok(index);
275	                        }
276	                    } else if closing.is_some() {
277	                        return Err(ProjectionError::MalformedSyntax {
278	                            offset: to_u32(index)?,
279	                            expected: "a matching delimiter",
280	                        });
281	                    } else {
282	                        index += 1;
283	                    }
284	                    can_start_expression = if byte == b')' {
285	                        let control = parens.pop().unwrap_or(false);
286	                        closed_control_paren = control;
287	                        control
288	                    } else if byte == b'}' {
289	                        closed_control_paren = false;
290	                        closed_block
291	                    } else {
292	                        closed_control_paren = false;
293	                        false
294	                    };
295	                    can_start_jsx = (byte == b'}' && closed_block) || can_start_expression;
296	                    pending_control_paren = false;
297	                }
298	                b'0'..=b'9' => {
299	                    index = self.skip_number(index);
300	                    can_start_expression = false;
301	                    can_start_jsx = false;
302	                    pending_control_paren = false;
303	                    closed_control_paren = false;
304	                }
305	                _ if self.identifier_start_width(index).is_some() => {
306	                    let end = self.skip_identifier(index);
307	                    let identifier = &self.bytes[index..end];
308	                    let type_position = identifier == b"void"
309	                        && previous_significant_byte(self.bytes, index) == Some(b':');
310	                    pending_control_paren = matches!(
311	                        identifier,
312	                        b"if" | b"for" | b"while" | b"with" | b"switch" | b"catch"
313	                    );
314	                    can_start_expression = !type_position
315	                        && (pending_control_paren
316	                            || matches!(
317	                                identifier,
318	                                b"return"
319	                                    | b"throw"
320	                                    | b"case"
321	                                    | b"delete"
322	                                    | b"void"
323	                                    | b"typeof"
324	                                    | b"new"
325	                                    | b"yield"
326	                                    | b"await"
327	                                    | b"in"
328	                                    | b"of"
329	                                    | b"instanceof"
330	                            ));
331	                    can_start_jsx = can_start_expression;
332	                    closed_control_paren = false;
333	                    index = end;
334	                }
335	                b'+' | b'-'
336	                    if self.bytes.get(index + 1) == Some(&byte) && !can_start_expression =>
337	                {
338	                    index += 2;
339	                    can_start_expression = false;
340	                    can_start_jsx = false;
341	                    pending_control_paren = false;
342	                    closed_control_paren = false;
343	                }
344	                b'!' if !can_start_expression => {
345	                    // In TypeScript expression position this is a postfix non-null assertion,
346	                    // so a following `/` is division rather than the start of a regexp.
347	                    index += 1;
348	                    can_start_expression = false;
349	                    can_start_jsx = false;
350	                    pending_control_paren = false;
351	                    closed_control_paren = false;
352	                }
353	                b'.' => {
354	                    index += if self.bytes.get(index..index + 3) == Some(b"...") { 3 } else { 1 };
355	                    can_start_expression = false;
356	                    can_start_jsx = false;
357	                    pending_control_paren = false;
358	                    closed_control_paren = false;
359	                }
360	                _ => {
361	                    index += 1;
362	                    can_start_expression = !matches!(byte, b']');
363	                    can_start_jsx = can_start_expression || matches!(byte, b';');
364	                    pending_control_paren = false;
365	                    closed_control_paren = false;
366	                }
367	            }
368	        }
369	
370	        if closing.is_some() {
371	            return Err(ProjectionError::UnterminatedSyntax {
372	                offset: to_u32(index.saturating_sub(1))?,
373	                construct: "delimited expression",
374	            });
375	        }
376	        Ok(index)
377	    }
378	}
