        for source in ["ifπ", r"if\u03c0", "if\u{0301}", r"if\u{1D49C}"] {
            assert!(!Scanner::new(source).bare_keyword_at(0, b"if"), "{source}");
        }
        assert!(Scanner::new("if (").bare_keyword_at(0, b"if"));
    }
}

