1	//! Emitting the projected text while recording which spans were copied verbatim, since only
2	//! those spans can carry a fix back to the author afterwards.
3	
4	use std::fmt::Write as _;
5	
6	use super::mapping::MappedProjection;
7	use crate::{
8	    diagnostics::{ProjectionError, to_u32},
9	    model::{
10	        ByteSpan, ClauseRole, ControlContext, ControlKind, EmbeddedKind, NONE, Overlay,
11	        ParserDynamicKind, StructuralKind,
12	    },
13	    projection_view::ProjectionSegment,
14	};
15	
16	pub(super) struct Builder<'a> {
17	    source: &'a str,
18	    overlay: &'a Overlay,
19	    prefix: &'a str,
20	    output: String,
21	    segments: Vec<ProjectionSegment>,
22	    cursor: usize,
23	    synthetic_callee_spans: Vec<(u32, u32)>,
24	}
25	impl<'a> Builder<'a> {
26	    pub(super) fn new(source: &'a str, overlay: &'a Overlay, prefix: &'a str) -> Self {
27	        let raw_style_bytes = overlay.style_blocks.iter().fold(0_usize, |bytes, style| {
28	            bytes.saturating_add(style.content.end.saturating_sub(style.content.start) as usize)
29	        });
30	        Self {
31	            source,
32	            overlay,
33	            prefix,
34	            output: String::with_capacity(
35	                source
36	                    .len()
37	                    .saturating_sub(raw_style_bytes)
38	                    .saturating_add(overlay.tokens.len().saturating_mul(64))
39	                    .saturating_add(overlay.embedded_tokens.len().saturating_mul(32))
40	                    .saturating_add(overlay.parser_shorthand_attributes.len().saturating_mul(8)),
41	            ),
42	            segments: Vec::with_capacity(
43	                overlay
44	                    .tokens
45	                    .len()
46	                    .saturating_mul(2)
47	                    .saturating_add(overlay.dynamic_tags.len())
48	                    .saturating_add(overlay.style_blocks.len())
49	                    .saturating_add(overlay.parser_shorthand_attributes.len().saturating_mul(2))
50	                    .saturating_add(1),
51	            ),
52	            cursor: 0,
53	            synthetic_callee_spans: Vec::new(),
54	        }
55	    }
56	
57	    pub(super) fn finish(mut self) -> Result<MappedProjection, ProjectionError> {
58	        self.copy_to(self.source.len())?;
59	        Ok(MappedProjection {
60	            projected: self.output,
61	            segments: self.segments,
62	            dynamic_prefix: None,
63	            dynamic_count: 0,
64	            dynamic_offsets: Vec::new(),
65	            synthetic_generator_spans: Vec::new(),
66	            synthetic_callee_spans: self.synthetic_callee_spans,
67	        })
68	    }
69	
70	    fn record_synthetic_callee(&mut self, start: usize) -> Result<(), ProjectionError> {
71	        self.synthetic_callee_spans.push((to_u32(start)?, to_u32(self.output.len())?));
72	        Ok(())
73	    }
74	
75	    fn copy_to(&mut self, end: usize) -> Result<(), ProjectionError> {
76	        if end < self.cursor || end > self.source.len() {
77	            return Err(ProjectionError::SourceChanged {
78	                offset: to_u32(end.min(self.source.len()))?,
79	            });
80	        }
81	        if end > self.cursor {
82	            let span = ByteSpan::new(to_u32(self.cursor)?, to_u32(end)?);
83	            self.copy_original(span)?;
84	            self.cursor = end;
85	        }
86	        Ok(())
87	    }
88	
89	    /// Copies an authored span and records it as a fixable segment. Every span this lane copies
90	    /// verbatim survives a round trip, so the parser can map a fix range back onto any of them.
91	    fn copy_original(&mut self, span: ByteSpan) -> Result<(), ProjectionError> {
92	        let start = span.start as usize;
93	        let end = span.end as usize;
94	        let Some(value) = self.source.get(start..end) else {
95	            return Err(ProjectionError::SourceChanged { offset: span.start });
96	        };
97	        let projected_start = to_u32(self.output.len())?;
98	        self.output.push_str(value);
99	        let projected_end = to_u32(self.output.len())?;
100	        if let Some(previous) = self.segments.last_mut()
101	            && previous.projected.end == projected_start
102	            && previous.original_start + (previous.projected.end - previous.projected.start)
103	                == span.start
104	        {
105	            previous.projected.end = projected_end;
106	        } else {
107	            self.segments.push(ProjectionSegment {
108	                projected: ByteSpan::new(projected_start, projected_end),
109	                original_start: span.start,
110	                fixable: true,
111	            });
112	        }
113	        Ok(())
114	    }
115	
116	    fn copy_original_omitting_lazy_patterns(
117	        &mut self,
118	        span: ByteSpan,
119	    ) -> Result<(), ProjectionError> {
120	        let mut cursor = span.start;
121	        for pattern in &self.overlay.parser_lazy_patterns {
122	            if pattern.ampersand < span.start || pattern.ampersand >= span.end {
123	                continue;
124	            }
125	            self.copy_original(ByteSpan::new(cursor, pattern.ampersand))?;
126	            cursor = pattern.ampersand.saturating_add(1);
127	        }
128	        self.copy_original(ByteSpan::new(cursor, span.end))
129	    }
130	
131	    pub(super) const fn original_cursor(&self) -> usize {
132	        self.cursor
133	    }
134	
135	    pub(super) fn wrapper_start(&mut self, node_index: u32) -> Result<(), ProjectionError> {
136	        let node = self.overlay.nodes[node_index as usize];
137	        self.copy_to(node.span.start as usize)?;
138	        if node.context == ControlContext::JsxChild {
139	            self.output.push('{');
140	        }
141	        let callee_start = self.output.len();
142	        write!(self.output, "{}W{node_index}_", self.prefix)
143	            .expect("writing to a String cannot fail");
144	        self.record_synthetic_callee(callee_start)?;
145	        write!(
146	            self.output,
147	            "({{async *{}M{node_index}_(){{/*{}N{node_index}S__*/",
148	            self.prefix, self.prefix
149	        )
150	        .expect("writing to a String cannot fail");
151	        Ok(())
152	    }
153	
154	    pub(super) fn wrapper_end(&mut self, node_index: u32) -> Result<(), ProjectionError> {
155	        let node = self.overlay.nodes[node_index as usize];
156	        self.copy_to(node.span.end as usize)?;
157	        write!(
158	            self.output,
159	            "/*{}N{node_index}E__*/}}}},{}E{node_index}_)",
160	            self.prefix, self.prefix
161	        )
162	        .expect("writing to a String cannot fail");
163	        if node.context == ControlContext::JsxChild {
164	            self.output.push('}');
165	        }
166	        Ok(())
167	    }
168	
169	    pub(super) fn try_end(&mut self, node_index: u32) -> Result<(), ProjectionError> {
170	        let node = self.overlay.nodes[node_index as usize];
171	        if node.kind != ControlKind::Try {
172	            return Err(ProjectionError::StructuralMismatch);
173	        }
174	        self.copy_to(node.span.end as usize)?;
175	        write!(self.output, "}},{}TE{node_index}_)", self.prefix)
176	            .expect("writing to a String cannot fail");
177	        Ok(())
178	    }
179	
180	    pub(super) fn token(&mut self, token_index: u32) -> Result<(), ProjectionError> {
181	        let token = self.overlay.tokens[token_index as usize];
182	        let start = token.span.start as usize;
183	        self.copy_to(start)?;
184	        let spelling = match token.kind {
185	            StructuralKind::FunctionBody => b"@{".as_slice(),
186	            StructuralKind::If => b"@if",
187	            StructuralKind::Else => b"@else",
188	            StructuralKind::For => b"@for",
189	            StructuralKind::Empty => b"@empty",
190	            StructuralKind::Switch => b"@switch",
191	            StructuralKind::Case => b"@case",
192	            StructuralKind::Default => b"@default",
193	            StructuralKind::Try => b"@try",
194	            StructuralKind::Pending => b"@pending",
195	            StructuralKind::Catch => b"@catch",
196	        };
197	        if self.source.as_bytes().get(start..start + spelling.len()) != Some(spelling) {
198	            return Err(ProjectionError::SourceChanged { offset: token.span.start });
199	        }
200	        match token.kind {
201	            StructuralKind::FunctionBody => {
202	                self.parser_function_body(token_index, start)?;
203	            }
204	            StructuralKind::Try => {
205	                if token.owner == NONE {
206	                    return Err(ProjectionError::StructuralMismatch);
207	                }
208	                write!(self.output, "/*{}{token_index}*/", self.prefix)
209	                    .expect("writing to a String cannot fail");
210	                let callee_start = self.output.len();
211	                write!(self.output, "{}T{}_", self.prefix, token.owner)
212	                    .expect("writing to a String cannot fail");
213	                self.record_synthetic_callee(callee_start)?;
214	                write!(self.output, "({{async *{}B{}_()", self.prefix, token.owner)
215	                    .expect("writing to a String cannot fail");
216	                self.cursor = start + spelling.len();
217	            }
218	            StructuralKind::Pending => {
219	                if token.owner == NONE {
220	                    return Err(ProjectionError::StructuralMismatch);
221	                }
222	                write!(
223	                    self.output,
224	                    ",/*{}{token_index}*/async *{}P{}_()",
225	                    self.prefix, self.prefix, token.owner
226	                )
227	                .expect("writing to a String cannot fail");
228	                self.cursor = start + spelling.len();
229	            }
230	            StructuralKind::Catch => {
231	                if token.owner == NONE {
232	                    return Err(ProjectionError::StructuralMismatch);
233	                }
234	                write!(
235	                    self.output,
236	                    ",/*{}{token_index}*/async *{}C{}_",
237	                    self.prefix, self.prefix, token.owner
238	                )
239	                .expect("writing to a String cannot fail");
240	                if !self.catch_has_header(token.owner)? {
241	                    self.output.push_str("()");
242	                }
243	                self.cursor = start + spelling.len();
244	            }
245	            kind => {
246	                write!(self.output, "/*{}{token_index}*/", self.prefix)
247	                    .expect("writing to a String cannot fail");
248	                if kind == StructuralKind::Empty {
249	                    self.output.push_str("if (false)");
250	                    self.cursor = start + spelling.len();
251	                } else {
252	                    self.cursor = start + 1;
253	                }
254	            }
255	        }
256	        Ok(())
257	    }
258	
259	    fn parser_function_body(
260	        &mut self,
261	        token_index: u32,
262	        start: usize,
263	    ) -> Result<(), ProjectionError> {
264	        // Keep the authored opening brace affine. A JSX-child code block then gets an
265	        // authenticated function wrapper so its body may contain statements; ordinary blocks
266	        // need only the marker after the brace.
267	        self.cursor = start + 1;
268	        self.copy_to(start + 2)?;
269	        if self.parser_code_block(token_index).is_some() {
270	            write!(
271	                self.output,
272	                "(async function*{}J{token_index}_(){{/*{}{token_index}*/",
273	                self.prefix, self.prefix
274	            )
275	            .expect("writing to a String cannot fail");
276	        } else {
277	            write!(self.output, "/*{}{token_index}*/", self.prefix)
278	                .expect("writing to a String cannot fail");
279	        }
280	        Ok(())
281	    }
282	
283	    fn parser_code_block(&self, token: u32) -> Option<usize> {
284	        self.overlay.parser_code_blocks.binary_search_by_key(&token, |block| block.token).ok()
285	    }
286	
287	    pub(super) fn parser_code_block_end(
288	        &mut self,
289	        block_index: u32,
290	    ) -> Result<(), ProjectionError> {
291	        let block = self
292	            .overlay
293	            .parser_code_blocks
294	            .get(block_index as usize)
295	            .ok_or(ProjectionError::StructuralMismatch)?;
296	        let closing =
297	            block.body.end.checked_sub(1).ok_or(ProjectionError::StructuralMismatch)? as usize;
298	        if self.source.as_bytes().get(closing) != Some(&b'}') {
299	            return Err(ProjectionError::SourceChanged {
300	                offset: block.body.end.saturating_sub(1),
301	            });
302	        }
303	        self.copy_to(closing)?;
304	        self.output.push_str("})");
305	        Ok(())
306	    }
307	
308	    fn catch_has_header(&self, node: u32) -> Result<bool, ProjectionError> {
309	        let mut clause = self.overlay.nodes[node as usize].first_clause;
310	        while clause != NONE {
311	            let current = self.overlay.clauses[clause as usize];
312	            if current.role == ClauseRole::Catch {
313	                return Ok(!current.header.is_empty());
314	            }
315	            clause = current.next;
316	        }
317	        Err(ProjectionError::StructuralMismatch)
318	    }
319	
320	    pub(super) fn header(
321	        &mut self,
322	        clause_index: u32,
323	        ordinal: u32,
324	    ) -> Result<(), ProjectionError> {
325	        let clause = self.overlay.clauses[clause_index as usize];
326	        let header = clause.for_header;
327	        if !header.annotated {
328	            return Err(ProjectionError::ScaffoldMismatch { index: ordinal as usize });
329	        }
330	        self.copy_to(clause.header.start as usize)?;
331	        self.output.push('(');
332	        self.copy_original_omitting_lazy_patterns(header.left)?;
333	        self.output.push_str(" of ");
334	        let callee_start = self.output.len();
335	        write!(self.output, "{}H{ordinal}_", self.prefix).expect("writing to a String cannot fail");
336	        self.record_synthetic_callee(callee_start)?;
337	        write!(self.output, "(/*{}R{ordinal}S__*/", self.prefix)
338	            .expect("writing to a String cannot fail");
339	        self.copy_original(header.right)?;
340	        write!(self.output, "/*{}R{ordinal}E__*/", self.prefix)
341	            .expect("writing to a String cannot fail");
342	        if !header.index.is_empty() {
343	            self.output.push(',');
344	            let callee_start = self.output.len();
345	            write!(self.output, "{}IH{ordinal}_", self.prefix)
346	                .expect("writing to a String cannot fail");
347	            self.record_synthetic_callee(callee_start)?;
348	            write!(self.output, "(/*{}I{ordinal}S__*/", self.prefix)
349	                .expect("writing to a String cannot fail");
350	            self.copy_original(header.index)?;
351	            write!(self.output, "/*{}I{ordinal}E__*/)", self.prefix)
352	                .expect("writing to a String cannot fail");
353	        }
354	        if !header.key.is_empty() {
355	            self.output.push(',');
356	            let callee_start = self.output.len();
357	            write!(self.output, "{}KH{ordinal}_", self.prefix)
358	                .expect("writing to a String cannot fail");
359	            self.record_synthetic_callee(callee_start)?;
360	            write!(self.output, "(/*{}K{ordinal}S__*/", self.prefix)
361	                .expect("writing to a String cannot fail");
362	            self.copy_original(header.key)?;
363	            write!(self.output, "/*{}K{ordinal}E__*/)", self.prefix)
364	                .expect("writing to a String cannot fail");
365	        }
366	        write!(self.output, ",{}HE{ordinal}_))", self.prefix)
367	            .expect("writing to a String cannot fail");
368	        self.cursor = clause.header.end as usize;
369	        Ok(())
370	    }
371	
372	    /// Projects the raw content of an inline `<style>` block.
373	    ///
374	    /// The parser lane rewrites dynamic openings and closings from `parser_dynamic_tokens`, which
375	    /// carry the authored closing expression this lane must retain, so `project_actions` routes
376	    /// only style content here.
377	    pub(super) fn embedded(&mut self, token_index: u32) -> Result<(), ProjectionError> {
378	        let token = self.overlay.embedded_tokens[token_index as usize];
379	        let marker = match token.kind {
380	            EmbeddedKind::StyleContent => {
381	                self.copy_to(token.span.start as usize)?;
382	                let style = self
383	                    .overlay
384	                    .style_blocks
385	                    .get(token.owner as usize)
386	                    .ok_or(ProjectionError::StructuralMismatch)?;
387	                if style.content != token.span {
388	                    return Err(ProjectionError::StructuralMismatch);
389	                }
390	                'S'
391	            }
392	            EmbeddedKind::ScriptContent => {
393	                self.copy_to(token.span.start as usize)?;
394	                let script = self
395	                    .overlay
396	                    .script_blocks
397	                    .get(token.owner as usize)
398	                    .ok_or(ProjectionError::StructuralMismatch)?;
399	                if script.content != token.span {
400	                    return Err(ProjectionError::StructuralMismatch);
401	                }
402	                'Q'
403	            }
404	            EmbeddedKind::DynamicOpen | EmbeddedKind::DynamicClose => return Ok(()),
405	        };
406	        write!(self.output, "{{/*{}{marker}{}__*/ null}}", self.prefix, token.owner)
407	            .expect("writing to a String cannot fail");
408	        self.cursor = token.span.end as usize;
409	        Ok(())
410	    }
411	
412	    pub(super) fn parser_dynamic(&mut self, token_index: u32) -> Result<(), ProjectionError> {
413	        let token = self.overlay.parser_dynamic_tokens[token_index as usize];
414	        let tag = self
415	            .overlay
416	            .dynamic_tags
417	            .get(token.owner as usize)
418	            .ok_or(ProjectionError::StructuralMismatch)?;
419	        match token.kind {
420	            ParserDynamicKind::OpenStart => {
421	                if token.offset != tag.opening.start
422	                    || self
423	                        .source
424	                        .as_bytes()
425	                        .get(tag.opening.start as usize..tag.expression.start as usize)
426	                        != Some(b"<{")
427	                {
428	                    return Err(ProjectionError::StructuralMismatch);
429	                }
430	                self.copy_to(tag.opening.start as usize)?;
431	                write!(
432	                    self.output,
433	                    "<{}D{} {}A{}_={{(",
434	                    self.prefix, token.owner, self.prefix, token.owner
435	                )
436	                .expect("writing to a String cannot fail");
437	                self.cursor = tag.expression.start as usize;
438	            }
439	            ParserDynamicKind::OpenEnd => {
440	                if token.offset != tag.expression.end
441	                    || tag.opening.end != tag.expression.end.saturating_add(1)
442	                    || self.source.as_bytes().get(tag.expression.end as usize) != Some(&b'}')
443	                {
444	                    return Err(ProjectionError::StructuralMismatch);
445	                }
446	                self.copy_to(tag.expression.end as usize)?;
447	                write!(self.output, ")}} {}Z{}_={{null}}", self.prefix, token.owner)
448	                    .expect("writing to a String cannot fail");
449	                self.cursor = tag.opening.end as usize;
450	            }
451	            ParserDynamicKind::CloseStart => {
452	                if token.offset != tag.closing.start
453	                    || self
454	                        .source
455	                        .as_bytes()
456	                        .get(tag.closing.start as usize..tag.closing_expression.start as usize)
457	                        != Some(b"</{")
458	                {
459	                    return Err(ProjectionError::StructuralMismatch);
460	                }
461	                self.copy_to(tag.closing.start as usize)?;
462	                self.output.push('{');
463	                let callee_start = self.output.len();
464	                write!(self.output, "{}C{}_", self.prefix, token.owner)
465	                    .expect("writing to a String cannot fail");
466	                self.record_synthetic_callee(callee_start)?;
467	                self.output.push_str("((");
468	                self.cursor = tag.closing_expression.start as usize;
469	            }
470	            ParserDynamicKind::CloseEnd => {
471	                if token.offset != tag.closing_expression.end
472	                    || tag.closing.end <= tag.closing_expression.end
473	                {
474	                    return Err(ProjectionError::StructuralMismatch);
475	                }
476	                self.copy_to(tag.closing_expression.end as usize)?;
477	                write!(self.output, "))}}</{}D{}>", self.prefix, token.owner)
478	                    .expect("writing to a String cannot fail");
479	                self.cursor = tag.closing.end as usize;
480	            }
481	        }
482	        Ok(())
483	    }
484	
485	    pub(super) fn parser_shorthand(&mut self, attribute_index: u32) -> Result<(), ProjectionError> {
486	        let attribute = self
487	            .overlay
488	            .parser_shorthand_attributes
489	            .get(attribute_index as usize)
490	            .ok_or(ProjectionError::StructuralMismatch)?;
491	        if attribute.span.start.saturating_add(1) != attribute.identifier.start
492	            || attribute.identifier.end.saturating_add(1) != attribute.span.end
493	            || self.source.as_bytes().get(attribute.span.start as usize) != Some(&b'{')
494	            || self.source.as_bytes().get(attribute.identifier.end as usize) != Some(&b'}')
495	        {
496	            return Err(ProjectionError::StructuralMismatch);
497	        }
498	        self.copy_to(attribute.span.start as usize)?;
499	        write!(self.output, "{}S{attribute_index}_", self.prefix)
500	            .expect("writing to a String cannot fail");
501	        self.output.push('=');
502	        self.copy_original(attribute.span)?;
503	        self.cursor = attribute.span.end as usize;
504	        Ok(())
505	    }
506	
507	    pub(super) fn parser_lazy_pattern(
508	        &mut self,
509	        pattern_index: u32,
510	    ) -> Result<(), ProjectionError> {
511	        let pattern = self
512	            .overlay
513	            .parser_lazy_patterns
514	            .get(pattern_index as usize)
515	            .ok_or(ProjectionError::StructuralMismatch)?;
516	        if pattern.pattern_start <= pattern.ampersand
517	            || self.source.as_bytes().get(pattern.ampersand as usize) != Some(&b'&')
518	        {
519	            return Err(ProjectionError::StructuralMismatch);
520	        }
521	        self.copy_to(pattern.ampersand as usize)?;
522	        self.cursor = pattern.ampersand.saturating_add(1) as usize;
523	        Ok(())
524	    }
525	}
