1	//! The projection expressed as an edit stream. Each kind of rewrite is derived from the overlay
2	//! on its own, then all of them are merged back into one source-ordered pass.
3	
4	use super::builder::Builder;
5	use crate::{
6	    diagnostics::{ProjectionError, to_u32},
7	    model::{ClauseRole, ControlContext, ControlKind, NONE, Overlay},
8	};
9	
10	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
11	pub(super) enum Action {
12	    TryEnd(u32),
13	    ParserCodeBlockEnd(u32),
14	    WrapperEnd(u32),
15	    WrapperStart(u32),
16	    Token(u32),
17	    Header { clause: u32, ordinal: u32 },
18	    Embedded(u32),
19	    ParserDynamic(u32),
20	    ParserShorthand(u32),
21	    ParserLazyPattern(u32),
22	}
23	
24	impl Action {
25	    pub(super) fn key(self, overlay: &Overlay) -> (u32, u8) {
26	        match self {
27	            Self::TryEnd(node) => (overlay.nodes[node as usize].span.end, 0),
28	            Self::ParserCodeBlockEnd(block) => {
29	                (overlay.parser_code_blocks[block as usize].body.end.saturating_sub(1), 0)
30	            }
31	            Self::WrapperEnd(node) => (overlay.nodes[node as usize].span.end, 1),
32	            Self::WrapperStart(node) => (overlay.nodes[node as usize].span.start, 2),
33	            Self::Token(token) => (overlay.tokens[token as usize].span.start, 3),
34	            Self::Header { clause, .. } => (overlay.clauses[clause as usize].header.start, 3),
