use tsrx_syntax::{project_for_format, project_for_parser};

#[test]
fn temp_dump_projection() {
    for source in [
        "function Counter() @{\n\tconst count = get()\n\n\t<button>\n\t\t{'Count: ' + count}\n\t</button>\n}\n",
        "function Counter() @{\n\tconst count = get();\n\n\t<button>\n\t\t{'Count: ' + count}\n\t</button>\n}\n",
    ] {
        match project_for_parser(source) {
            Ok(projection) => println!("=== parser projection:\n{}\n", projection.source()),
            Err(error) => println!("=== parser projection error: {error:?}"),
        }
        match project_for_format(source) {
            Ok(projection) => println!("=== format projection:\n{}\n", projection.source()),
            Err(error) => println!("=== format projection error: {error:?}"),
        }
    }
}

