        Self {
            bytes,
            tokens: Vec::with_capacity(bytes.len().div_ceil(384)),
            nodes: Vec::with_capacity(bytes.len().div_ceil(1024)),
            clauses: Vec::with_capacity(bytes.len().div_ceil(512)),
